<?php
require_once __DIR__ . '/../includes/db.php'; require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/activity.php';
require_role('super_admin','sport_admin'); $pdo=db(); $admin=current_admin(); $all=is_super_admin();
$ids=[]; if(!$all){$st=$pdo->prepare('SELECT sport_id FROM admin_sports WHERE admin_id=?');$st->execute([$admin['id']]);$ids=array_map('intval',$st->fetchAll(PDO::FETCH_COLUMN));if(!$ids&&!empty($admin['sport_id']))$ids=[(int)$admin['sport_id']];}
$where=$all?'':' AND s.id IN ('.implode(',', $ids?:[0]).')';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$status=$_POST['status']??'';$remarks=trim($_POST['remarks']??'');if(!in_array($status,['approved','returned','disqualified'],true))throw new RuntimeException('Choose a valid review decision.');$q=$pdo->prepare('SELECT ee.id FROM event_entries ee JOIN events e ON e.id=ee.event_id JOIN sports s ON s.id=e.sport_id WHERE ee.id=?'.$where);$q->execute([$id]);if(!$q->fetch())throw new RuntimeException('That entry is outside your assigned sport desk.');$pdo->prepare('UPDATE event_entries SET status=?,remarks=?,reviewed_at=NOW(),reviewed_by=? WHERE id=? AND status IN (\'submitted\',\'returned\')')->execute([$status,$remarks?:null,$admin['id'],$id]);log_activity('reviewed_event_entry','event_entry',$id,'Marked entry '.$status.'.');flash('success','Entry decision saved.');}catch(Throwable $e){flash('error',$e->getMessage());}header('Location: entry_review.php');exit;}
$entries=$pdo->query("SELECT ee.*,a.full_name,a.lrn,d.name area_name,e.name event_name,s.name sport_name FROM event_entries ee JOIN athletes a ON a.id=ee.athlete_id JOIN delegations d ON d.id=ee.area_id JOIN events e ON e.id=ee.event_id JOIN sports s ON s.id=e.sport_id WHERE ee.status IN ('submitted','returned')$where ORDER BY ee.submitted_at,ee.created_at")->fetchAll();
require_once __DIR__ . '/../includes/layout.php';page_head('Entry Approvals');
?>
<div class="admin-hero"><div><span class="eyebrow">Sports Administrator desk</span><h1>Entry Approvals</h1><p class="admin-subtitle">Validate submitted athlete entries before they become official lists.</p></div></div><?php if($m=flash('error')):?><div class="notice error"><?= htmlspecialchars($m) ?></div><?php endif;?><?php if($m=flash('success')):?><div class="notice success"><?= htmlspecialchars($m) ?></div><?php endif;?>
<div class="table-card admin-users-table"><table class="score-table"><thead><tr><th>Athlete</th><th>Area</th><th>Sport / event</th><th>Coach</th><th>Decision</th></tr></thead><tbody><?php foreach($entries as $entry):?><tr><td><strong><?=htmlspecialchars($entry['full_name'])?></strong><br><small><?=htmlspecialchars($entry['lrn'])?></small></td><td><?=htmlspecialchars($entry['area_name'])?></td><td><?=htmlspecialchars($entry['sport_name'])?><br><small><?=htmlspecialchars($entry['event_name'])?></small></td><td><?=htmlspecialchars($entry['coach_name']?:'Not provided')?></td><td><form method="post" class="review-form"><input type="hidden" name="id" value="<?=$entry['id']?>"><select name="status"><option value="approved">Approve</option><option value="returned">Return for correction</option><option value="disqualified">Disqualify</option></select><input name="remarks" maxlength="500" placeholder="Remarks (required when returning)"><button class="btn secondary">Save</button></form></td></tr><?php endforeach;?><?php if(!$entries):?><tr><td colspan="5" class="empty">No entries await review.</td></tr><?php endif;?></tbody></table></div><?php page_foot();?>
